//! The shipped menu: what this build knows exists, before anything is installed.
//!
//! The base install carries a catalog, not the packs. A person (or, later, an agent proposing work) can read
//! what is on the shelf and fetch exactly one thing; nothing here runs, writes or downloads. The index is
//! generated by the packs repository and copied into `docs/packs/INDEX.json` at release, so the binary knows
//! the shelf offline and the shelf can still be replaced by a cached copy fetched at run time.

use serde_json::Value;

/// Embedded at build time: shipping a data file next to the binary would make the reference depend on where
/// the binary was installed, and the menu is small enough that carrying it is free.
const SHIPPED: &str = include_str!("../../../docs/packs/INDEX.json");

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Row {
    pub id: String,
    pub version: String,
    pub title: String,
    pub summary: String,
    pub keywords: Vec<String>,
    pub kinds: Vec<String>,
    pub items: Vec<String>,
    pub requires_hades: String,
    pub bytes: u64,
    pub sha256: String,
    pub archive: String,
    /// The triple a connector archive was built for. Absent on a data pack, which runs anywhere Hades runs.
    pub platform: Option<String>,
}

impl Row {
    /// Whether this pack is worth showing for a query. Every word has to land somewhere, so `review diff`
    /// matches and `review kubernetes` does not; a single word matches the id, the title, the summary or any
    /// keyword.
    pub fn matches(&self, query: &str) -> bool {
        let words: Vec<String> = query
            .split_whitespace()
            .map(|word| word.to_lowercase())
            .filter(|word| !word.is_empty())
            .collect();
        if words.is_empty() {
            return true;
        }
        let haystack = format!(
            "{} {} {} {} {}",
            self.id,
            self.title,
            self.summary,
            self.keywords.join(" "),
            self.items.join(" ")
        )
        .to_lowercase();
        words.iter().all(|word| haystack.contains(word))
    }

    fn line(&self) -> String {
        let kind = match &self.platform {
            Some(triple) => format!("{}/{}", self.kinds.join(","), triple),
            None => self.kinds.join(","),
        };
        format!(
            "{:<26} {:<22} {:<10} {}",
            self.id,
            kind,
            self.version,
            self.summary
        )
    }
}

/// Read the shipped index. A malformed index is an error rather than an empty shelf: "no pack matches" and
/// "the menu could not be read" are different answers, and only one of them should send someone off to write
/// a skill by hand.
pub fn shipped() -> Result<Vec<Row>, String> {
    parse(SHIPPED)
}

pub fn parse(text: &str) -> Result<Vec<Row>, String> {
    let value: Value = serde_json::from_str(text)
        .map_err(|error| format!("the pack index is not JSON: {error}"))?;
    let packs = value
        .get("packs")
        .and_then(Value::as_array)
        .ok_or_else(|| "the pack index has no `packs` array".to_string())?;
    let mut rows = Vec::new();
    for (index, entry) in packs.iter().enumerate() {
        let object = entry
            .as_object()
            .ok_or_else(|| format!("pack {} is not an object", index + 1))?;
        let text = |key: &str| {
            object
                .get(key)
                .and_then(Value::as_str)
                .map(str::to_string)
                .ok_or_else(|| format!("pack {} has no `{key}`", index + 1))
        };
        let mut kinds = Vec::new();
        let mut items = Vec::new();
        for item in object
            .get("items")
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default()
        {
            if let Some(kind) = item.get("kind").and_then(Value::as_str)
                && !kinds.iter().any(|seen| seen == kind)
            {
                kinds.push(kind.to_string());
            }
            if let Some(name) = item.get("name").and_then(Value::as_str) {
                items.push(name.to_string());
            }
        }
        rows.push(Row {
            id: text("id")?,
            version: text("version")?,
            title: text("title")?,
            summary: text("summary")?,
            keywords: object
                .get("keywords")
                .and_then(Value::as_array)
                .map(|words| {
                    words
                        .iter()
                        .filter_map(Value::as_str)
                        .map(str::to_string)
                        .collect()
                })
                .unwrap_or_default(),
            kinds,
            items,
            requires_hades: text("requires_hades")?,
            bytes: object.get("bytes").and_then(Value::as_u64).unwrap_or(0),
            sha256: text("sha256")?,
            archive: text("archive")?,
            platform: object
                .get("platform")
                .and_then(Value::as_str)
                .map(str::to_string),
        });
    }
    Ok(rows)
}

/// What `hades pack menu` prints: the shelf, in id order, with the digest short enough to compare by eye and
/// the full value in `--json`.
pub fn render(rows: &[Row]) -> String {
    if rows.is_empty() {
        return "the shelf is empty".to_string();
    }
    let mut text = String::new();
    for row in rows {
        text.push_str(&row.line());
        text.push('\n');
    }
    text.push_str(&format!(
        "\n{} {}. `hades pack find <words>` narrows it; `hades pack inspect` reads an archive.\n",
        rows.len(),
        if rows.len() == 1 { "pack" } else { "packs" }
    ));
    text
}

/// How old a cached shelf is, in words. A menu that cannot say when it was read is a menu that looks current
/// when it is not; the shipped copy says that instead of a date, because it is as old as the binary.
pub fn age_text(seconds: u64) -> String {
    match seconds {
        0..=90 => "just now".to_string(),
        _ if seconds < 3_600 => format!("{} minutes ago", seconds / 60),
        _ if seconds < 86_400 => format!("{} hours ago", seconds / 3_600),
        _ if seconds < 7 * 86_400 => format!("{} days ago", seconds / 86_400),
        _ => format!("{} days ago, older than a week", seconds / 86_400),
    }
}

pub fn find<'a>(rows: &'a [Row], query: &str) -> Vec<&'a Row> {
    rows.iter().filter(|row| row.matches(query)).collect()
}

#[cfg(test)]
mod tests {
    #[test]
    fn an_age_is_said_in_words() {
        assert_eq!(super::age_text(5), "just now");
        assert_eq!(super::age_text(600), "10 minutes ago");
        assert_eq!(super::age_text(7_200), "2 hours ago");
        assert_eq!(super::age_text(2 * 86_400), "2 days ago");
        assert!(super::age_text(9 * 86_400).contains("older than a week"));
    }

    use super::*;

    #[test]
    fn the_shipped_index_reads_and_lists_every_pack() {
        let rows = shipped().expect("the shipped index");
        assert!(!rows.is_empty(), "a binary with no shelf cannot check one");
        for row in &rows {
            assert!(!row.sha256.is_empty(), "{} has no digest", row.id);
            assert!(row.sha256.len() == 64, "{} has a truncated digest", row.id);
            assert!(row.archive.starts_with("dist/"), "{}", row.archive);
        }
    }

    #[test]
    fn a_query_matches_the_id_the_summary_and_the_keywords() {
        let rows = shipped().expect("the shipped index");
        let by_id = find(&rows, "review-a-diff");
        assert_eq!(by_id.len(), 1, "{by_id:?}");
        let by_keyword = find(&rows, "citations");
        assert!(
            by_keyword
                .iter()
                .any(|row| row.id == "research-with-sources")
        );
        let two_words = find(&rows, "research sources");
        assert_eq!(two_words.len(), 1, "{two_words:?}");
        assert!(find(&rows, "research kubernetes").is_empty());
        assert!(
            find(&rows, "").len() == rows.len(),
            "an empty query lists all"
        );
    }

    #[test]
    fn a_malformed_index_is_an_error_not_an_empty_shelf() {
        let said = parse(r#"{"packs":[{"id":"x"}]}"#).expect_err("half a row");
        assert!(said.contains("version"), "{said}");
        assert!(parse("not json").is_err());
    }
}
